import React from "react";
import { Container, Row, Col } from "react-bootstrap";

export default function Shows() {
  // Simple placeholder shows section — replace with real data later.
  const upcoming = [
    {
      date: "Nov 12, 2025",
      venue: "The Grand Hall",
      city: "San Francisco",
      img: "img/bg-img/a1.jpg",
    },
    {
      date: "Dec 03, 2025",
      venue: "Riverside Arena",
      city: "Portland",
      img: "img/bg-img/a2.jpg",
    },
    {
      date: "Jan 15, 2026",
      venue: "Downtown Theater",
      city: "Seattle",
      img: "img/bg-img/a3.jpg",
    },
  ];

  return (
    <section id="shows" className="shows-area section-padding-100">
      <Container>
        <Row>
          <Col>
            <div className="section-heading style-2 text-center mb-4">
              <p>On the Road</p>
              <h2>Upcoming Shows</h2>
            </div>
          </Col>
        </Row>

        <Row className="justify-content-center">
          {upcoming.map((s, i) => (
            <Col key={i} xs={12} md={4} className="mb-3">
              <div className="single-show text-center p-3 border rounded bg-white">
                {s.img && (
                  <img
                    src={s.img}
                    alt={s.venue}
                    className="img-fluid mb-2 rounded"
                    loading="lazy"
                  />
                )}
                <h5 className="mb-1">{s.venue}</h5>
                <p className="mb-0 text-muted">{s.city}</p>
                <p className="mt-2 fw-bold">{s.date}</p>
              </div>
            </Col>
          ))}
        </Row>
      </Container>
    </section>
  );
}
